#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Generate the launcher's C# string tables from shared/i18n/launcher."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from catalogue import ROOT, load

TARGET = ROOT / "launcher" / "LauncherStrings.g.cs"
BANNER = (
    "// Generated by tools/i18n/gen_launcher_strings.py from\n"
    "// shared/i18n/launcher/launcher.yaml. Do not edit by hand.\n"
)


def csharp(text: str) -> str:
    return json.dumps(text, ensure_ascii=False)


def render() -> bytes:
    result = load()
    if result.errors:
        raise SystemExit("i18n errors; run tools/i18n/check.py")
    entries = [entry for entry in result.entries if entry["id"].startswith("hoa.launcher.")]
    lines = [
        BANNER,
        "using System.Collections.Generic;",
        "",
        "namespace HordesOfAzeroth.Launcher",
        "{",
        "    static class LauncherStrings",
        "    {",
        "        public static readonly Dictionary<string, string> EnUs = new Dictionary<string, string>",
        "        {",
    ]
    for entry in entries:
        lines.append(f"            [{csharp(entry['id'])}] = {csharp(entry['enUS'])},")
    lines += [
        "        };",
        "",
        "        public static readonly Dictionary<string, string> ZhCn = new Dictionary<string, string>",
        "        {",
    ]
    for entry in entries:
        lines.append(f"            [{csharp(entry['id'])}] = {csharp(entry['zhCN'])},")
    lines += [
        "        };",
        "",
        "        public static readonly Dictionary<string, string> ZhTw = new Dictionary<string, string>",
        "        {",
    ]
    for entry in entries:
        lines.append(f"            [{csharp(entry['id'])}] = {csharp(entry.get('zhTW', entry['enUS']))},")
    lines += [
        "        };",
        "",
        "        public static readonly Dictionary<string, string> EnglishToId = new Dictionary<string, string>",
        "        {",
    ]
    for entry in entries:
        lines.append(f"            [{csharp(entry['enUS'])}] = {csharp(entry['id'])},")
    lines += [
        "        };",
        "    }",
        "}",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    payload = render()
    if args.check:
        current = TARGET.read_bytes() if TARGET.exists() else b""
        if current != payload:
            print("launcher strings are out of date; run tools/i18n/gen_launcher_strings.py")
            return 1
        print("launcher strings: ok")
        return 0
    TARGET.write_bytes(payload)
    print(f"wrote {TARGET.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
